create or replace function public.sync_active_cart(p_client_reference text,p_items jsonb,p_files jsonb default '[]'::jsonb) returns uuid language plpgsql security invoker set search_path='' as $$ declare v_uid uuid:=auth.uid();v_cart uuid;v_item jsonb;v_opt jsonb;v_file jsonb;v_item_id uuid; begin if v_uid is null then raise exception 'Authentication required';end if; select id into v_cart from public.carts where customer_id=v_uid and status='active' limit 1; if v_cart is null then insert into public.carts(customer_id,client_reference) values(v_uid,p_client_reference) returning id into v_cart;end if; delete from public.cart_items where cart_id=v_cart; for v_item in select * from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop insert into public.cart_items(cart_id,customer_id,client_item_id,product_id,variant_id,product_name,quantity,unit_price) values(v_cart,v_uid,v_item->>'id',nullif(v_item->>'productId','')::uuid,nullif(v_item->>'variantId','')::uuid,v_item->>'name',greatest(1,(v_item->>'qty')::int),greatest(0,(v_item->>'unitPrice')::numeric)) returning id into v_item_id; for v_opt in select * from jsonb_array_elements(coalesce(v_item->'options','[]'::jsonb)) loop insert into public.cart_item_options(cart_item_id,option_name,option_value,position) values(v_item_id,v_opt->>'name',v_opt->>'value',coalesce((v_opt->>'position')::int,0)); end loop; end loop; for v_file in select * from jsonb_array_elements(coalesce(p_files,'[]'::jsonb)) loop select id into v_item_id from public.cart_items where cart_id=v_cart and client_item_id=v_file->>'cartItemId'; insert into public.cart_files(cart_id,cart_item_id,customer_id,client_file_id,bucket,storage_path,original_name,mime_type,size_bytes) values(v_cart,v_item_id,v_uid,v_file->>'id',coalesce(nullif(v_file->>'bucket',''),'croma-arquivos'),v_file->>'path',v_file->>'name',v_file->>'type',coalesce((v_file->>'size')::bigint,0)) on conflict(storage_path) do update set cart_id=excluded.cart_id,cart_item_id=excluded.cart_item_id,client_file_id=excluded.client_file_id; end loop; delete from public.cart_files cf where cf.cart_id=v_cart and not exists(select 1 from jsonb_array_elements(coalesce(p_files,'[]'::jsonb)) x where x->>'path'=cf.storage_path); update public.carts set updated_at=now() where id=v_cart; return v_cart; end $$; revoke all on function public.sync_active_cart(text,jsonb,jsonb) from public,anon; grant execute on function public.sync_active_cart(text,jsonb,jsonb) to authenticated;